6	import org.springframework.stereotype.Component;
7	import org.springframework.transaction.annotation.Propagation;
8	import org.springframework.transaction.annotation.Transactional;
9	
10	/**
11	 * 幂等记录占坑/回写的独立事务边界。
12	 *
13	 * <p>必须经独立 Bean 调用，避免同类自调用导致 {@link Propagation#REQUIRES_NEW} 代理失效：
14	 * 占坑行立即提交以便并发请求感知；业务事务回滚不影响已存档的首次结果。</p>
15	 */
16	@Component
17	public class IdempotentTxBoundary {
18	
19	    private final IdempotentRecordRepository records;
20	    private final TimeService timeService;
21	
22	    public IdempotentTxBoundary(IdempotentRecordRepository records, TimeService timeService) {
23	        this.records = records;
24	        this.timeService = timeService;
25	    }
26	
27	    /**
28	     * 独立事务占坑，立即提交。
29	     */
