3	import java.time.OffsetDateTime;
4	import java.util.Map;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ResponseEntity;
7	import org.springframework.web.bind.MethodArgumentNotValidException;
8	import org.springframework.web.bind.annotation.ExceptionHandler;
9	import org.springframework.web.bind.annotation.RestControllerAdvice;
10	
11	/**
12	 * 统一异常响应。
13	 */
14	@RestControllerAdvice
15	public class GlobalExceptionHandler {
16	
17	    /**
18	     * 业务异常按携带状态码返回。
19	     */
20	    @ExceptionHandler(ApiException.class)
21	    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
22	        return ResponseEntity.status(ex.getStatus()).body(body(ex.getStatus(), ex.getMessage()));
23	    }
24	
25	    /**
26	     * Bean 校验失败统一 400。
27	     */
28	    @ExceptionHandler(MethodArgumentNotValidException.class)
29	    public ResponseEntity<Map<String, Object>> handleValid(MethodArgumentNotValidException ex) {
30	        String msg = ex.getBindingResult().getFieldErrors().stream()
31	                .findFirst()
32	                .map(e -> e.getField() + ": " + e.getDefaultMessage())
33	                .orElse("请求参数校验失败");
34	        return ResponseEntity.badRequest().body(body(400, msg));
35	    }
36	
37	    /**
38	     * 兜底 500，不泄露堆栈。
39	     */
40	    @ExceptionHandler(Exception.class)
41	    public ResponseEntity<Map<String, Object>> handleOther(Exception ex) {
42	        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
43	                .body(body(500, "服务内部错误"));
44	    }
