1	package com.example.rebate.service;
2	
3	import com.example.rebate.domain.BatchStatus;
4	import com.example.rebate.domain.DeclarationBatch;
5	import com.example.rebate.domain.Doubt;
6	import com.example.rebate.domain.DoubtStatus;
7	import com.example.rebate.repo.BatchRepository;
8	import com.example.rebate.repo.CheckDetailRepository;
9	import com.example.rebate.repo.DoubtRepository;
10	import com.example.rebate.repo.LateEventRepository;
11	import com.example.rebate.support.TimeService;
12	import com.example.rebate.web.ConflictException;
13	import com.example.rebate.web.NotFoundException;
14	import com.example.rebate.web.UnprocessableException;
15	import com.example.rebate.web.dto.BatchView;
16	import com.example.rebate.web.dto.LateEventView;
17	import java.util.List;
18	import org.springframework.stereotype.Service;
19	import org.springframework.transaction.annotation.Transactional;
20	
21	/**
22	 * 正式申报、审核、撤批、结案流转。
23	 */
24	@Service
25	public class DeclarationService {
26	
27	    private final BatchRepository batchRepo;
28	    private final DoubtRepository doubtRepo;
29	    private final CheckDetailRepository detailRepo;
30	    private final LateEventRepository lateEventRepo;
31	    private final TimeService timeService;
32	
33	    public DeclarationService(BatchRepository batchRepo,
34	                              DoubtRepository doubtRepo,
35	                              CheckDetailRepository detailRepo,
36	                              LateEventRepository lateEventRepo,
37	                              TimeService timeService) {
38	        this.batchRepo = batchRepo;
39	        this.doubtRepo = doubtRepo;
40	        this.detailRepo = detailRepo;
41	        this.lateEventRepo = lateEventRepo;
42	        this.timeService = timeService;
43	    }
44	
45	    /**
46	     * 正式申报：批次冻结。
47	     *
48	     * <p>{@code reviewConfirmed=true} 时在本事务内把“已说明待复核”的疑点一并复核确认；
49	     * 若仍存在未解除疑点（含未提交说明者），整体回滚——批次不会被报出，疑点也不被部分改写。</p>
50	     */
51	    @Transactional
52	    public BatchView declare(String batchNo, boolean reviewConfirmed) {
53	        DeclarationBatch batch = loadBatch(batchNo);
54	        if (batch.status() != BatchStatus.CHECKED && batch.status() != BatchStatus.DOUBTFUL) {
55	            throw new ConflictException("批次当前状态 " + batch.status() + " 不允许正式申报");
56	        }
57	        List<Doubt> doubts = doubtRepo.findByBatchId(batch.id());
58	        if (reviewConfirmed) {
59	            for (Doubt d : doubts) {
60	                if (d.status() == DoubtStatus.EXPLAINED) {
61	                    doubtRepo.reviewResolve(d.id(), timeService.now());
62	                }
63	            }
64	        }
65	        List<Doubt> unresolved = doubtRepo.findUnresolvedByBatchId(batch.id());
66	        if (!unresolved.isEmpty()) {
67	            throw new UnprocessableException(
68	                    "存在 " + unresolved.size() + " 个未解除疑点，禁止正式申报");
69	        }
70	        batchRepo.freeze(batch.id(), timeService.now());
71	        return BatchViews.batch(batchRepo.findById(batch.id()).orElseThrow());
72	    }
73	
74	    /**
75	     * 审核通过：DECLARED -> APPROVED。
76	     */
77	    @Transactional
78	    public BatchView approve(String batchNo) {
79	        DeclarationBatch batch = loadBatch(batchNo);
80	        if (batch.status() != BatchStatus.DECLARED) {
81	            throw new ConflictException("批次当前状态 " + batch.status() + " 不允许审核");
82	        }
83	        batchRepo.updateStatus(batch.id(), BatchStatus.APPROVED,
84	                batch.totalDeclaredTax(), timeService.now());
85	        return BatchViews.batch(batchRepo.findById(batch.id()).orElseThrow());
86	    }
87	
88	    /**
89	     * 撤批：整体作废并释放全部关联单证及占用登记，不得部分撤出。仅允许在退库之前。
90	     */
91	    @Transactional
