3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	/**
7	 * 退税计算规则（纯函数，便于复算与测试）。
8	 *
9	 * <ul>
10	 *   <li>计税依据 = FOB 价 × 退税率（保留 4 位小数，四舍五入）；</li>
11	 *   <li>换汇成本 = 计税依据 ÷ FOB 美元价（保留 6 位小数，四舍五入），合法区间 [5.0, 8.0]，恰在端点合法；</li>
12	 *   <li>到账差异比例 = |到账金额 − 申报税额| ÷ 申报税额（保留 8 位小数），恰 0.5%（0.005）视为一致。</li>
13	 * </ul>
14	 */
15	public final class RebateCalculator {
16	
17	    /** 换汇成本下限（含）。 */
18	    public static final BigDecimal EXCHANGE_COST_MIN = new BigDecimal("5.0");
19	
20	    /** 换汇成本上限（含）。 */
21	    public static final BigDecimal EXCHANGE_COST_MAX = new BigDecimal("8.0");
22	
23	    /** 到账差异容忍比例：恰 0.5% 视为一致。 */
24	    public static final BigDecimal DIFF_TOLERANCE = new BigDecimal("0.005");
25	
26	    private static final int TAX_SCALE = 4;
27	    private static final int COST_SCALE = 6;
28	    private static final int RATIO_SCALE = 8;
29	
30	    private RebateCalculator() {
31	    }
32	
33	    /**
34	     * 计税依据 = FOB 价 × 退税率。
35	     */
36	    public static BigDecimal taxBasis(BigDecimal fobAmount, BigDecimal rebateRate) {
37	        return fobAmount.multiply(rebateRate).setScale(TAX_SCALE, RoundingMode.HALF_UP);
38	    }
39	
40	    /**
41	     * 换汇成本 = 计税依据 ÷ FOB 美元价。
42	     */
43	    public static BigDecimal exchangeCost(BigDecimal taxBasis, BigDecimal fobUsd) {
44	        return taxBasis.divide(fobUsd, COST_SCALE, RoundingMode.HALF_UP);
45	    }
46	
47	    /**
48	     * 换汇成本是否在 [5.0, 8.0] 内（含端点）。按 {@code compareTo} 比较，标度差异不影响结果。
49	     */
50	    public static boolean exchangeCostInRange(BigDecimal exchangeCost) {
51	        return exchangeCost.compareTo(EXCHANGE_COST_MIN) >= 0
52	                && exchangeCost.compareTo(EXCHANGE_COST_MAX) <= 0;
53	    }
54	
55	    /**
56	     * 到账与申报税额差额（绝对值，保留 4 位）。
57	     */
58	    public static BigDecimal diffAmount(BigDecimal declaredTax, BigDecimal receivedAmount) {
59	        return receivedAmount.subtract(declaredTax).abs().setScale(TAX_SCALE, RoundingMode.HALF_UP);
60	    }
61	
62	    /**
63	     * 到账差异比例 = |到账 − 申报| ÷ 申报。
64	     */
65	    public static BigDecimal diffRatio(BigDecimal declaredTax, BigDecimal receivedAmount) {
66	        BigDecimal diff = diffAmount(declaredTax, receivedAmount);
67	        return diff.divide(declaredTax, RATIO_SCALE, RoundingMode.HALF_UP);
68	    }
69	
70	    /**
71	     * 差异是否在容忍范围内：比例不超过 0.005，恰 0.5% 视为一致。
72	     */
73	    public static boolean diffConsistent(BigDecimal diffRatio) {
74	        return diffRatio.compareTo(DIFF_TOLERANCE) <= 0;
75	    }
76	}
